import com.sun.net.httpserver.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.concurrent.*;

public class Main {
 static final Path ROOT=Paths.get(System.getProperty("user.dir")).toAbsolutePath();
 static final Path DATA=ROOT.resolve("data/store.json"); static final int PORT=Integer.parseInt(System.getProperty("port","8080"));
 static Map<String,Object> db=new LinkedHashMap<>(); static Map<String,String> sessions=new ConcurrentHashMap<>();
 @SuppressWarnings("unchecked") static Map<String,Object> map(Object o){return o instanceof Map?(Map<String,Object>)o:new LinkedHashMap<>();}
 @SuppressWarnings("unchecked") static List<Object> list(Object o){return o instanceof List?(List<Object>)o:new ArrayList<>();}
 static String s(Object o){return o==null?"":String.valueOf(o);} static Map<String,Object> obj(Object... a){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)m.put((String)a[i],a[i+1]);return m;}
 static synchronized void save(){try{Files.createDirectories(DATA.getParent());Files.writeString(DATA,Json.stringify(db),StandardCharsets.UTF_8);}catch(Exception e){e.printStackTrace();}}
 static synchronized void load(){try{Files.createDirectories(DATA.getParent());if(Files.exists(DATA))db=map(Json.parse(Files.readString(DATA)));}catch(Exception e){db=new LinkedHashMap<>();} if(db.isEmpty()){db=obj("users",new ArrayList<>(),"appointments",new ArrayList<>(),"activities",new ArrayList<>(),"nextQueue",1); addUser("Clinic Administrator","admin","admin@clinic.local","09170000000","admin123","staff");addUser("Dr. Santos","doctor","doctor@clinic.local","09170000001","doctor123","staff");save();}}
 static String hash(String x){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(b);}catch(Exception e){return x;}}
 static synchronized Map<String,Object> addUser(String name,String username,String email,String mobile,String pass,String role){Map<String,Object> u=obj("id",UUID.randomUUID().toString(),"fullName",name,"username",username,"email",email,"mobile",mobile,"password",hash(pass),"role",role,"createdAt",Instant.now().toString());list(db.get("users")).add(u);return u;}
 static void activity(String msg){list(db.get("activities")).add(0,obj("message",msg,"time",LocalDateTime.now().format(DateTimeFormatter.ofPattern("h:mm a"))));List<Object>a=list(db.get("activities"));while(a.size()>30)a.remove(a.size()-1);}
 static void send(HttpExchange x,int status,Object body)throws IOException{byte[] b=Json.stringify(body).getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.getResponseHeaders().set("Access-Control-Allow-Origin","*");x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type");x.getResponseHeaders().set("Access-Control-Allow-Methods","GET,POST,PUT,DELETE,OPTIONS");x.sendResponseHeaders(status,b.length);x.getResponseBody().write(b);x.close();}
 static Map<String,Object> body(HttpExchange x)throws IOException{return map(Json.parse(new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8)));}
 static String cookie(HttpExchange x,String key){String c=x.getRequestHeaders().getFirst("Cookie");if(c!=null)for(String p:c.split(";")){String[]kv=p.trim().split("=",2);if(kv.length==2&&kv[0].equals(key))return kv[1];}return "";}
 static Map<String,Object> user(HttpExchange x){return map(db.get("_none")).isEmpty()?findUser(sessions.get(cookie(x,"ql_session"))):new LinkedHashMap<>();}
 static Map<String,Object> findUser(String id){for(Object o:list(db.get("users"))){Map<String,Object>u=map(o);if(s(u.get("id")).equals(id))return u;}return null;}
 static Map<String,Object> safeUser(Map<String,Object>u){return obj("id",u.get("id"),"fullName",u.get("fullName"),"username",u.get("username"),"email",u.get("email"),"mobile",u.get("mobile"),"role",u.get("role"));}
 static boolean staff(Map<String,Object>u){return u!=null&&s(u.get("role")).equals("staff");}
 static Map<String,Object> appointmentById(String id){for(Object o:list(db.get("appointments"))){Map<String,Object>a=map(o);if(s(a.get("id")).equals(id))return a;}return null;}
 static String date(Object o){return s(o);}
 static boolean validSlot(String d,String t){try{LocalDate day=LocalDate.parse(d);if(day.getDayOfWeek().getValue()>5)return false;LocalTime time=LocalTime.parse(t);return !time.isBefore(LocalTime.of(8,0))&&!time.isAfter(LocalTime.of(16,0))&&!(!time.isBefore(LocalTime.of(11,0))&&time.isBefore(LocalTime.of(12,0)))&&!time.equals(LocalTime.NOON);}catch(Exception e){return false;}}
 static void handle(HttpExchange x)throws IOException{String path=x.getRequestURI().getPath(),method=x.getRequestMethod();if(method.equals("OPTIONS")){send(x,204,obj());return;}try{
  if(path.startsWith("/api/")){Map<String,Object>b=method.equals("GET")?new LinkedHashMap<>():body(x);Map<String,Object>u=findUser(sessions.get(cookie(x,"ql_session")));
   if(path.equals("/api/auth/signup")&&method.equals("POST")){String role=s(b.get("role"));if(!role.equals("patient")&&!role.equals("staff"))role="patient";String email=s(b.get("email")).toLowerCase(),mobile=s(b.get("mobile"));if(s(b.get("fullName")).isBlank()||s(b.get("username")).isBlank()||email.isBlank()||mobile.isBlank()||s(b.get("password")).length()<6||!s(b.get("password")).equals(s(b.get("confirmPassword")))){send(x,400,obj("error","Please complete all fields. Passwords must match and contain at least 6 characters."));return;}for(Object z:list(db.get("users"))){Map<String,Object>v=map(z);if(email.equalsIgnoreCase(s(v.get("email")))||mobile.equals(s(v.get("mobile")))||s(b.get("username")).equalsIgnoreCase(s(v.get("username")))){send(x,409,obj("error","Email, mobile number, or username is already registered."));return;}}Map<String,Object>nu=addUser(s(b.get("fullName")),s(b.get("username")),email,mobile,s(b.get("password")),role);String token=UUID.randomUUID().toString();sessions.put(token,s(nu.get("id")));x.getResponseHeaders().add("Set-Cookie","ql_session="+token+"; Path=/; HttpOnly; SameSite=Lax");save();send(x,200,obj("user",safeUser(nu)));return;}
   if(path.equals("/api/auth/login")&&method.equals("POST")){String identity=s(b.get("identity")).toLowerCase(),role=s(b.get("role"));Map<String,Object>found=null;for(Object z:list(db.get("users"))){Map<String,Object>v=map(z);if((s(v.get("email")).equalsIgnoreCase(identity)||s(v.get("mobile")).equals(identity)||s(v.get("username")).equalsIgnoreCase(identity))&&s(v.get("password")).equals(hash(s(b.get("password"))))&&s(v.get("role")).equals(role)){found=v;break;}}if(found==null){send(x,401,obj("error","Incorrect login details or account type."));return;}String token=UUID.randomUUID().toString();sessions.put(token,s(found.get("id")));x.getResponseHeaders().add("Set-Cookie","ql_session="+token+"; Path=/; HttpOnly; SameSite=Lax");send(x,200,obj("user",safeUser(found)));return;}
   if(path.equals("/api/auth/logout")){String token=cookie(x,"ql_session");sessions.remove(token);x.getResponseHeaders().add("Set-Cookie","ql_session=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax");send(x,200,obj("ok",true));return;}
   if(path.equals("/api/auth/me")){send(x,200,obj("user",u==null?null:safeUser(u)));return;}
   if(path.equals("/api/auth/forgot")){String id=s(b.get("identity"));boolean exists=false;for(Object z:list(db.get("users"))){Map<String,Object>v=map(z);if(s(v.get("email")).equalsIgnoreCase(id)||s(v.get("mobile")).equals(id))exists=true;}String code=String.format("%06d",new Random().nextInt(1000000));if(exists){db.put("reset_"+id,code);save();}send(x,200,obj("message",exists?"If the account exists, a verification code has been generated.":"If the account exists, a verification code has been generated.","demoCode",exists?code:null));return;}
   if(path.equals("/api/auth/reset")&&method.equals("POST")){String id=s(b.get("identity")),code=s(b.get("code"));if(!code.equals(s(db.get("reset_"+id)))){send(x,400,obj("error","Invalid verification code."));return;}for(Object z:list(db.get("users"))){Map<String,Object>v=map(z);if(s(v.get("email")).equalsIgnoreCase(id)||s(v.get("mobile")).equals(id))v.put("password",hash(s(b.get("password"))));}db.remove("reset_"+id);save();send(x,200,obj("ok",true));return;}
   if(u==null){send(x,401,obj("error","Please log in to continue."));return;}
   if(path.equals("/api/patient/profile")&&method.equals("POST")){if(!s(u.get("role")).equals("patient")){send(x,403,obj("error","Patient access only."));return;}u.put("age",b.get("age"));u.put("sex",b.get("sex"));u.put("category",b.get("category"));u.put("registered",true);save();send(x,200,obj("user",safeUser(u),"profile",obj("age",u.get("age"),"sex",u.get("sex"),"category",u.get("category"))));return;}
   if(path.equals("/api/patient/profile")&&method.equals("GET")){send(x,200,obj("user",safeUser(u),"profile",obj("age",u.get("age"),"sex",u.get("sex"),"category",u.get("category")),"registered",Boolean.TRUE.equals(u.get("registered"))));return;}
   if(path.equals("/api/appointments")&&method.equals("POST")){if(!s(u.get("role")).equals("patient")){send(x,403,obj("error","Patient access only."));return;}if(!Boolean.TRUE.equals(u.get("registered"))){send(x,400,obj("error","Complete patient registration first."));return;}String d=s(b.get("date")),t=s(b.get("time")),service=s(b.get("service"));if(!validSlot(d,t)){send(x,400,obj("error","Choose Monday to Friday, 8:00 AM–5:00 PM. 11:00 AM–12:00 PM is lunch break."));return;}for(Object z:list(db.get("appointments"))){Map<String,Object>a=map(z);if(d.equals(s(a.get("date")))&&t.equals(s(a.get("time")))&&!s(a.get("status")).equals("Cancelled")&&!s(a.get("status")).equals("No-Show")&&!s(a.get("status")).equals("Re-Assigned")){send(x,409,obj("error","That appointment slot is no longer available. Please choose another time."));return;}}if(service.isBlank()){send(x,400,obj("error","Select a medical service."));return;}int q=((Number)db.get("nextQueue")).intValue();db.put("nextQueue",q+1);Map<String,Object>a=obj("id",UUID.randomUUID().toString(),"patientId",u.get("id"),"patientName",u.get("fullName"),"category",u.get("category"),"age",u.get("age"),"sex",u.get("sex"),"mobile",u.get("mobile"),"email",u.get("email"),"service",service,"date",d,"time",t,"queue",q,"status","Waiting","doctor","To be assigned","createdAt",Instant.now().toString(),"walkIn",false);list(db.get("appointments")).add(a);activity("Q"+q+" appointment booked by "+u.get("fullName"));save();send(x,200,obj("appointment",a));return;}
   if(path.equals("/api/appointments")&&method.equals("GET")){List<Object>out=new ArrayList<>();for(Object z:list(db.get("appointments"))){Map<String,Object>a=map(z);if(staff(u)||s(a.get("patientId")).equals(s(u.get("id"))))out.add(a);}send(x,200,obj("appointments",out));return;}
   if(path.equals("/api/appointments/cancel")&&method.equals("POST")){Map<String,Object>a=appointmentById(s(b.get("id")));if(a==null||(!staff(u)&&!s(a.get("patientId")).equals(s(u.get("id"))))){send(x,404,obj("error","Appointment not found."));return;}if(!s(a.get("status")).equals("Waiting")){send(x,400,obj("error","Only waiting appointments can be cancelled."));return;}a.put("status","Cancelled");a.put("cancelledAt",Instant.now().toString());activity("Q"+a.get("queue")+" cancelled");save();send(x,200,obj("appointment",a));return;}
   if(path.equals("/api/staff/dashboard")){if(!staff(u)){send(x,403,obj("error","Staff access only."));return;}List<Object>ap=list(db.get("appointments"));LocalDate today=LocalDate.now();int todays=0,in=0,completed=0;Map<String,Integer>counts=obj("No-Show",0,"Cancelled",0,"Completed",0,"Checking",0,"Waiting",0,"Re-Assigned",0).entrySet().stream().collect(LinkedHashMap::new,(m,e)->m.put(e.getKey(),(Integer)e.getValue()),Map::putAll);for(Object z:ap){Map<String,Object>a=map(z);if(today.toString().equals(s(a.get("date")))){todays++;String st=s(a.get("status"));counts.put(st,counts.getOrDefault(st,0)+1);if(st.equals("Waiting")||st.equals("Checking"))in++;if(st.equals("Completed"))completed++;}}send(x,200,obj("totalPatients",list(db.get("users")).stream().filter(z->s(map(z).get("role")).equals("patient")).count(),"todaysAppointments",todays,"inQueue",in,"completedToday",completed,"counts",counts,"activities",list(db.get("activities")).subList(0,Math.min(8,list(db.get("activities")).size()))));return;}
   if(path.equals("/api/staff/queue")&&method.equals("GET")){if(!staff(u)){send(x,403,obj("error","Staff access only."));return;}send(x,200,obj("appointments",list(db.get("appointments"))));return;}
   if(path.equals("/api/staff/action")&&method.equals("POST")){if(!staff(u)){send(x,403,obj("error","Staff access only."));return;}Map<String,Object>a=appointmentById(s(b.get("id")));String action=s(b.get("action"));if(a==null){send(x,404,obj("error","Appointment not found."));return;}String st=s(a.get("status"));if(action.equals("checking")&&st.equals("Waiting")){a.put("status","Checking");}else if(action.equals("complete")&&st.equals("Checking")){a.put("status","Completed");}else if(action.equals("no-show")&&st.equals("Waiting")){a.put("status","No-Show");}else if(action.equals("reassign")&&(st.equals("Cancelled")||st.equals("No-Show"))){String patient=s(b.get("patientName"));if(patient.isBlank()){send(x,400,obj("error","Enter the walk-in patient's full name."));return;}int q=((Number)db.get("nextQueue")).intValue();db.put("nextQueue",q+1);Map<String,Object>nw=obj("id",UUID.randomUUID().toString(),"patientId","walkin-"+UUID.randomUUID(),"patientName",patient,"category",s(b.get("category")),"age",s(b.get("age")),"sex",s(b.get("sex")),"mobile",s(b.get("mobile")),"email","","service",a.get("service"),"date",a.get("date"),"time",a.get("time"),"queue",q,"status","Waiting","doctor","To be assigned","createdAt",Instant.now().toString(),"walkIn",true,"reassignedFrom",a.get("id"));list(db.get("appointments")).add(nw);a.put("reassignedTo",nw.get("id"));a.put("status","Re-Assigned");activity("Released slot Q"+a.get("queue")+" reassigned to walk-in Q"+q);save();send(x,200,obj("appointment",a,"newAppointment",nw));return;}else{send(x,400,obj("error","That action is not allowed for the current appointment status."));return;}activity("Q"+a.get("queue")+" updated to "+a.get("status"));save();send(x,200,obj("appointment",a));return;}
   if(path.equals("/api/staff/walkin")&&method.equals("POST")){if(!staff(u)){send(x,403,obj("error","Staff access only."));return;}String name=s(b.get("fullName"));if(name.isBlank()){send(x,400,obj("error","Patient name is required."));return;}int q=((Number)db.get("nextQueue")).intValue();db.put("nextQueue",q+1);Map<String,Object>a=obj("id",UUID.randomUUID().toString(),"patientId","walkin-"+UUID.randomUUID(),"patientName",name,"category",s(b.get("category")),"age",s(b.get("age")),"sex",s(b.get("sex")),"mobile",s(b.get("mobile")),"email","","service",s(b.get("service")),"date",LocalDate.now().toString(),"time",LocalTime.now().toString(),"queue",q,"status","Waiting","doctor","To be assigned","createdAt",Instant.now().toString(),"walkIn",true);list(db.get("appointments")).add(a);activity("Walk-in patient "+name+" added as Q"+q);save();send(x,200,obj("appointment",a));return;}
   if(path.equals("/api/staff/patients")){if(!staff(u)){send(x,403,obj("error","Staff access only."));return;}List<Object>p=new ArrayList<>();for(Object z:list(db.get("users"))){Map<String,Object>v=map(z);if(s(v.get("role")).equals("patient"))p.add(obj("id",v.get("id"),"fullName",v.get("fullName"),"age",v.get("age"),"sex",v.get("sex"),"mobile",v.get("mobile"),"email",v.get("email"),"category",v.get("category")));}send(x,200,obj("patients",p));return;}
   if(path.startsWith("/api/staff/patient/")&&method.equals("GET")){if(!staff(u)){send(x,403,obj("error","Staff access only."));return;}String id=path.substring("/api/staff/patient/".length());Map<String,Object>p=findUser(id);if(p==null){send(x,404,obj("error","Patient not found."));return;}List<Object>hist=new ArrayList<>();for(Object z:list(db.get("appointments")))if(s(map(z).get("patientId")).equals(id))hist.add(z);send(x,200,obj("patient",obj("id",p.get("id"),"fullName",p.get("fullName"),"mobile",p.get("mobile"),"email",p.get("email"),"age",p.get("age"),"sex",p.get("sex"),"category",p.get("category")),"history",hist));return;}
   send(x,404,obj("error","API endpoint not found."));return;
  }
  // Static files
  String rel=path.equals("/")?"index.html":path.substring(1);Path f=ROOT.resolve("public").resolve(rel).normalize();if(!f.startsWith(ROOT.resolve("public"))||!Files.exists(f)||Files.isDirectory(f)){send(x,404,obj("error","Not found"));return;}String ct=rel.endsWith(".css")?"text/css":rel.endsWith(".js")?"application/javascript":rel.endsWith(".svg")?"image/svg+xml":rel.endsWith(".png")?"image/png":"text/html";byte[]bytes=Files.readAllBytes(f);x.getResponseHeaders().set("Content-Type",ct+"; charset=utf-8");x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);x.close();
 }catch(Exception e){e.printStackTrace();send(x,500,obj("error","Server error: "+e.getMessage()));}}
 public static void main(String[]args)throws Exception{load();HttpServer server=HttpServer.create(new InetSocketAddress(PORT),0);server.createContext("/",Main::handle);server.setExecutor(Executors.newCachedThreadPool());server.start();System.out.println("QueueLess Clinic running at http://localhost:"+PORT);System.out.println("Demo staff: admin@clinic.local / admin123 | doctor@clinic.local / doctor123");}
 static class Json{static String stringify(Object o){if(o==null)return"null";if(o instanceof String||o instanceof Character)return"\""+esc(String.valueOf(o))+"\"";if(o instanceof Number||o instanceof Boolean)return o.toString();if(o instanceof Map){StringJoiner j=new StringJoiner(",","{","}");((Map<?,?>)o).forEach((k,v)->j.add(stringify(String.valueOf(k))+":"+stringify(v)));return j.toString();}if(o instanceof Iterable){StringJoiner j=new StringJoiner(",","[","]");for(Object v:(Iterable<?>)o)j.add(stringify(v));return j.toString();}return stringify(String.valueOf(o));}static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t");}static Object parse(String s){return new Parser(s).value();}static class Parser{String s;int i=0;Parser(String s){this.s=s;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}Object value(){ws();if(i>=s.length())return null;char c=s.charAt(i);if(c=='{')return object();if(c=='[')return array();if(c=='"')return str();if(s.startsWith("true",i)){i+=4;return true;}if(s.startsWith("false",i)){i+=5;return false;}if(s.startsWith("null",i)){i+=4;return null;}int st=i;while(i<s.length()&&"-0123456789.eE".indexOf(s.charAt(i))>=0)i++;try{return Double.valueOf(s.substring(st,i));}catch(Exception e){return null;}}Map<String,Object>object(){Map<String,Object>m=new LinkedHashMap<>();i++;ws();while(i<s.length()&&s.charAt(i)!='}'){String k=str();ws();i++;Object v=value();m.put(k,v);ws();if(i<s.length()&&s.charAt(i)==','){i++;ws();}else break;}if(i<s.length())i++;return m;}List<Object>array(){List<Object>a=new ArrayList<>();i++;ws();while(i<s.length()&&s.charAt(i)!=']'){a.add(value());ws();if(i<s.length()&&s.charAt(i)==','){i++;ws();}else break;}if(i<s.length())i++;return a;}String str(){i++;StringBuilder b=new StringBuilder();while(i<s.length()){char c=s.charAt(i++);if(c=='"')break;if(c=='\\'&&i<s.length()){char n=s.charAt(i++);switch(n){case'n':b.append('\n');break;case'r':b.append('\r');break;case't':b.append('\t');break;default:b.append(n);}}else b.append(c);}return b.toString();}}}
}
